let parsed = {};
let rawText = "";
const inputJson = $json;

if (inputJson.output && inputJson.output[0] && inputJson.output[0].content && inputJson.output[0].content[0]) {
  const c = inputJson.output[0].content[0];
  if (typeof c.text === "object" && c.text !== null) parsed = c.text;
  else if (typeof c.text === "string") rawText = c.text;
} else if (inputJson.text) {
  if (typeof inputJson.text === "object") parsed = inputJson.text;
  else rawText = inputJson.text;
}

if (Object.keys(parsed).length === 0 && rawText) {
  try {
    parsed = JSON.parse(rawText.replace(/```json/gi, "").replace(/```/g, "").trim());
  } catch (err) {
    try {
      const s = rawText.indexOf("{");
      const e = rawText.lastIndexOf("}");
      if (s !== -1 && e !== -1) parsed = JSON.parse(rawText.slice(s, e + 1));
    } catch (e2) { parsed = {}; }
  }
}

let lead = {};
try {
  lead = $("Verify Lead State in Response Tab").first().json || {};
} catch (e) {
  try {
    lead = $("Verify Lead State in Response Tab").item.json || {};
  } catch (e2) { lead = {}; }
}

function clean(str) {
  return String(str || "")
    .replace(/\*\*/g, "")
    .replace(/(?<!\w)\*(?!\*)/g, "")
    .replace(/`/g, "")
    .replace(/\s*[\u2014\u2013]\s*/g, ", ")
    .replace(/\s+,/g, ",")
    .replace(/,\s*$/g, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}
function escapeHtml(str) {
  return String(str || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .trim();
}
function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
function endWithPeriod(s) {
  return s && !/[.!?]$/.test(s) ? s + "." : s;
}

// Clean recipient name (avoid alphanumeric email handles like nidhishrathore0011)
let rawRecipient = clean(lead.full_name || lead.first_name || lead.First_Name || lead.name || "");
if (!rawRecipient || ["there", "valued lead", "undefined", "null", "friend"].includes(rawRecipient.toLowerCase())) {
  const emailVal = lead.Email || lead.email || "";
  const emailUser = String(emailVal).split("@")[0] || "";
  const alphaOnly = emailUser.replace(/\d+/g, "").split(/[._-]+/).filter(Boolean);
  rawRecipient = alphaOnly.length > 0 ? alphaOnly[0] : "Friend";
} else {
  rawRecipient = rawRecipient.split(/[ ._-]/)[0].replace(/\d+/g, "") || "Friend";
}
const recipientName = rawRecipient.charAt(0).toUpperCase() + rawRecipient.slice(1).toLowerCase();

let resolvedBrand = String(lead.Brand || lead.brand || "").trim();
if (!resolvedBrand && parsed.brand && String(parsed.brand).trim().toLowerCase() !== "brand") resolvedBrand = parsed.brand;
const brandDisplay = clean(resolvedBrand).replace(/[^\p{L}\p{N} &'.\-]/gu, "").replace(/\s{2,}/g, " ").trim() || "your brand";
const brandHtml = escapeHtml(brandDisplay);
const brandDot = brandDisplay.toUpperCase().replace(/["\\]/g, "");

const layerStyles = {
  attract: { fill: "#ff8c38", agentFill: "#ffe2c7" },
  convert: { fill: "#7b16ff", agentFill: "#ded0ff" },
  scale:   { fill: "#00966b", agentFill: "#c7f7d4" },
  support: { fill: "#ff3355", agentFill: "#ffd0d8" },
  retain:  { fill: "#008ba3", agentFill: "#c8f3ff" },
  brain:   { fill: "#8d4200", agentFill: "#d5e2ff" }
};

let nodesDef = "";
let edgesDef = "";
const hubId = "hub_circle";
nodesDef += "  " + hubId + " [label=\"...\", shape=circle, style=filled, fillcolor=\"#e2e8f0\", color=\"#94a3b8\", width=0.5, fixedsize=true, fontsize=10];\n";
const rootNodeId = "master_root";
nodesDef += "  " + rootNodeId + " [label=\"" + brandDot + " AI\\nOps Layer\", shape=oval, style=filled, fillcolor=\"#f1f5f9\", color=\"#94a3b8\", fontsize=9];\n";

let i = 0;
for (const [key, style] of Object.entries(layerStyles)) {
  const agents = parsed[key];
  if (!Array.isArray(agents) || agents.length === 0) continue;

  const layerNodeId = "layer_" + key;
  nodesDef += "  " + layerNodeId + " [label=\"" + key.toUpperCase() + "\", shape=box, style=\"filled,rounded\", fillcolor=\"" + style.fill + "\", fontcolor=\"#ffffff\", fontsize=10, width=1.1, height=0.45];\n";
  edgesDef += "  " + rootNodeId + " -> " + layerNodeId + ";\n";

  agents.forEach((agent) => {
    i++;
    const id = "agent_" + i;
    const title = escapeHtml(clean(agent.name || "Agent"));
    const desc = escapeHtml(clean(agent.desc || ""));
    const htmlLabel = "<<table border=\"0\" cellborder=\"0\" cellpadding=\"4\" cellspacing=\"0\"><tr><td><b><font point-size=\"9\">" + title + "</font></b></td></tr><tr><td><font point-size=\"8\" color=\"#334155\">" + desc + "</font></td></tr></table>>";
    nodesDef += "  " + id + " [label=" + htmlLabel + ", shape=box, style=\"filled,rounded\", fillcolor=\"" + style.agentFill + "\", color=\"#94a3b8\", margin=\"0.1,0.06\"];\n";
    edgesDef += "  " + layerNodeId + " -> " + id + ";\n";
    edgesDef += "  " + id + " -> " + hubId + ";\n";
  });
}

const dotGraph = "digraph G {\n  graph [rankdir=LR, nodesep=0.25, ranksep=0.7, bgcolor=\"#ffffff\", label=\"" + brandDot + " AI OPS LAYER\\n \", labelloc=\"t\", fontsize=18, fontname=\"Helvetica-Bold\"];\n  node [fontname=\"Helvetica\"];\n  edge [color=\"#cbd5e1\", penwidth=1.0, arrowhead=none];\n\n" + nodesDef + edgesDef + "}";

let hook = clean(parsed.achievement_hook);
let closer = endWithPeriod(clean(parsed.hook_closer));

if (!hook) hook = brandDisplay + " has built something its customers keep coming back to.";
if (!closer) closer = "That's the hard part, and it's already done.";

if (hook.toLowerCase().includes(closer.toLowerCase().replace(/\.$/, ""))) {
  hook = hook.replace(new RegExp(escapeRegex(closer.replace(/\.$/, "")) + "\\.?", "i"), "").trim();
}
hook = endWithPeriod(hook);

let verticalFocus = clean(parsed.vertical_focus) || "Direct-to-consumer acquisition, community-driven repeat purchase, and content-led trust cycles.";
verticalFocus = endWithPeriod(verticalFocus.replace(/The agents we'd build reflect that\\.?/i, "").trim());

function matchIndustrySegment(raw) {
  const norm = String(raw || "").toLowerCase().trim().replace(/[^a-z0-9]/g, "");
  if (!norm) return "D2C-General";
  if (norm.includes("apparel") || norm.includes("fashion") || norm.includes("clothing") || norm.includes("wear")) return "D2C-Apparel";
  if (norm.includes("hospitality") || norm.includes("hotel") || norm.includes("resort") || norm.includes("lodge")) return "Hospitality";
  if (norm.includes("travel") || norm.includes("tour") || norm.includes("expedition") || norm.includes("trip")) return "Travel";
  if (norm.includes("fitness") || norm.includes("gym") || norm.includes("workout") || norm.includes("crossfit")) return "Fitness";
  if (norm.includes("health") || norm.includes("clinic") || norm.includes("medical") || norm.includes("doctor") || norm.includes("dental") || norm.includes("pharma")) return "Health";
  if (norm.includes("realestate") || norm.includes("realty") || norm.includes("property") || norm.includes("brokerage") || norm.includes("realtor")) return "Real Estate";
  if (norm.includes("agency") || norm.includes("marketing") || norm.includes("advertising") || norm.includes("media") || norm.includes("creative")) return "Marketing Agency";
  if (norm.includes("beauty") || norm.includes("cosmetic") || norm.includes("skincare") || norm.includes("makeup") || norm.includes("haircare")) return "D2C-Beauty";
  if (norm.includes("food") || norm.includes("beverage") || norm.includes("coffee") || norm.includes("tea") || norm.includes("drink") || norm.includes("snack") || norm.includes("bakery")) return "D2C-Food&Beverage";
  if (norm.includes("wellness") || norm.includes("supplement") || norm.includes("vitamin") || norm.includes("nutrition") || norm.includes("mental")) return "D2C-Wellness";
  if (norm.includes("home") || norm.includes("furniture") || norm.includes("decor") || norm.includes("kitchen") || norm.includes("bedding") || norm.includes("goods")) return "D2C-HomeGoods";
  if (norm.includes("d2c") || norm.includes("ecommerce") || norm.includes("retail")) return "D2C-General";
  return "D2C-General";
}

const rawIndustry = lead.Industry || lead.industry || parsed.industry || "";
const matchedIndustry = matchIndustrySegment(rawIndustry);

let bodyTpl = "";
let sigTpl = "";
let callBookingUrl = "https://calendly.com/team-grapelabs/30min";
let waUrl = "https://wa.me/918388892300?text=Hi%20Kashika,%20saw%20your%20email%20about%20our%20AI%20ops%20layer";
let callBtnText = "Book a Free Call";
let waBtnText = "Text me on WhatsApp";
let subjectTpl = "You were curious. So we got to work. Here's {{brand}}'s entire AI ops layer.";
let senderName = "Kashika Gupta";

let cfg = null;
try {
  cfg = $("Fetch Config").first()?.json?.emailTemplate;
} catch (e1) {}
if (!cfg) {
  try {
    const wh = $("Webhook").first()?.json;
    cfg = wh?.body?.emailTemplate || wh?.emailTemplate;
  } catch (e2) {}
}

if (cfg) {
  if (cfg.signatureHtml) sigTpl = cfg.signatureHtml;
  if (cfg.callUrl) callBookingUrl = cfg.callUrl;
  if (cfg.whatsappUrl) waUrl = cfg.whatsappUrl;
  if (cfg.callButtonText) callBtnText = cfg.callButtonText;
  if (cfg.whatsappText) waBtnText = cfg.whatsappText;
  if (cfg.senderName) senderName = cfg.senderName;

  if (cfg.industryTemplates && cfg.industryTemplates[matchedIndustry]) {
    const indTpl = cfg.industryTemplates[matchedIndustry];
    if (indTpl.bodyHtml) bodyTpl = indTpl.bodyHtml;
    if (indTpl.subject) subjectTpl = indTpl.subject;
  }

  if (!bodyTpl && cfg.bodyHtml) bodyTpl = cfg.bodyHtml;
  if (!subjectTpl && cfg.subject) subjectTpl = cfg.subject;
}

if (waUrl.includes("{{brand}}")) {
  waUrl = waUrl.replace(/\{\{\s*brand\s*\}\}/gi, encodeURIComponent(brandDisplay));
}

if (!sigTpl) {
  sigTpl = `<div style="margin-top: 22px; line-height: 1.45; font-size: 13px; color: #374151;">
  <div style="margin-bottom: 4px;">Best,</div>
  <div style="margin-bottom: 14px; font-weight: 600; color: #111827;">Kashika Gupta</div>
  <div style="border-left: 2px solid #7c3aed; padding-left: 10px; margin-bottom: 18px;">
    <div style="color: #6d28d9; font-weight: 600; font-size: 13px;">Co-Founder, GrapeLabs AI</div>
    <div style="color: #6b7280; font-size: 12px; margin-top: 2px;">Green Park, New Delhi · 110016</div>
    <div style="color: #6b7280; font-size: 12px; margin-top: 2px;">Phone: +91 83888 92300</div>
  </div>
  <div style="font-size: 12px; color: #6b7280; font-style: italic;">
    P.S. The irony isn't lost on us. We used our own infrastructure to find you, track your open, and send you this.
  </div>
</div>`;
}

if (!bodyTpl) {
  bodyTpl = `<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 1.55; color: #111827;">
  Hi {{first_name}},<br><br>
  {{achievement_hook}} <b>{{hook_closer}}</b><br><br>
  The part that compounds that at this stage is the ops layer underneath, and <b>in 2026 that's exactly where AI should be doing the heavy lifting.</b> Most D2C tools are horizontal, built for every brand and optimised for none. What we build is vertical: an infrastructure designed specifically around how {{brand}} acquires, converts, and retains. {{vertical_focus}} <b>The agents we'd build reflect that.</b><br><br>
  <b>Not a platform. Not generic automation. A system.</b><br><br>
  I've attached a visual of what that infrastructure looks like for {{brand}} specifically, the agents, how they connect, and what each one runs. Worth 20 minutes to see what this would look like for {{brand}}? No pitch, no deck, just what we'd fix first. Book a slot or shoot a text if you have any questions.<br><br>
  <!-- CTA Buttons -->
  <table border="0" cellpadding="0" cellspacing="0" style="margin: 18px 0 16px 0;">
    <tr>
      <td style="padding-right: 12px; padding-bottom: 8px;">
        <a href="{{call_url}}" style="display: inline-block; background-color: #581c87; color: #ffffff; text-decoration: none; padding: 12px 22px; border-radius: 6px; font-weight: 700; font-size: 14px; line-height: 1.2; text-align: center;">{{call_button_text}}</a>
      </td>
      <td style="padding-bottom: 8px;">
        <a href="{{whatsapp_url}}" style="display: inline-block; background-color: #25D366; color: #ffffff; text-decoration: none; padding: 12px 22px; border-radius: 6px; font-weight: 700; font-size: 14px; line-height: 1.2; text-align: center;">{{whatsapp_text}}</a>
      </td>
    </tr>
  </table>
</div>`;
}

let htmlEmail = bodyTpl
  .replace(/\{\{\s*first_name\s*\}\}/gi, escapeHtml(recipientName))
  .replace(/\{\{\s*recipientName\s*\}\}/gi, escapeHtml(recipientName))
  .replace(/\{\{\s*brand\s*\}\}/gi, brandHtml)
  .replace(/\{\{\s*achievement_hook\s*\}\}/gi, escapeHtml(hook))
  .replace(/\{\{\s*hook_closer\s*\}\}/gi, escapeHtml(closer))
  .replace(/\{\{\s*vertical_focus\s*\}\}/gi, escapeHtml(verticalFocus))
  .replace(/\{\{\s*call_url\s*\}\}/gi, callBookingUrl)
  .replace(/\{\{\s*whatsapp_url\s*\}\}/gi, waUrl)
  .replace(/\{\{\s*call_button_text\s*\}\}/gi, callBtnText)
  .replace(/\{\{\s*whatsapp_text\s*\}\}/gi, waBtnText)
  .replace(/\{\{\s*sender_name\s*\}\}/gi, senderName);

if (htmlEmail.includes("{{signature}}")) {
  htmlEmail = htmlEmail.replace(/\{\{\s*signature\s*\}\}/gi, sigTpl);
}

const subjectOverride = clean(parsed.subject_override);
const exactSubject = subjectOverride || subjectTpl.replace(/\{\{\s*brand\s*\}\}/gi, brandDisplay);

const rawJson = JSON.stringify({
  attract: parsed.attract || [], convert: parsed.convert || [], scale: parsed.scale || [],
  support: parsed.support || [], retain: parsed.retain || [], brain: parsed.brain || [],
  achievement_hook: hook, hook_closer: closer, vertical_focus: verticalFocus,
  signature_html: sigTpl,
  call_url: callBookingUrl,
  whatsapp_url: waUrl,
  call_button_text: callBtnText,
  whatsapp_text: waBtnText,
  matched_industry: matchedIndustry
});

return {
  ...lead,
  ...parsed,
  brand: brandDisplay,
  email: lead.lead_email || lead.Email || lead.email || "",
  row_number: lead.row_number,
  full_name: recipientName,
  first_name: recipientName,
  industry: matchedIndustry,
  achievement_hook: hook,
  hook_closer: closer,
  vertical_focus: verticalFocus,
  email_subject: exactSubject,
  email_body: htmlEmail,
  dot_source: dotGraph,
  raw_json: rawJson
};

