  _found: false,
  is_already_sent: false,
  lead_email: targetEmail,
  action,
  chat_id: target.chat_id,
  edit_text: editText,
  reason: ''
};

// --- approve / reject / edit: look up the row by the email in the button ---
if (['approve', 'reject', 'edit'].includes(action)) {
  if (!targetEmail) return [{ json: { ...base, reason: 'No email found in the button data' } }];

  const record = [...allRows].reverse().find(item => {
    const rowEmail = String(item.json.Email || item.json.email || '').toLowerCase().trim();
    return rowEmail === targetEmail;
  });
  if (!record) return [{ json: { ...base, reason: 'Lead not found in Automation response tab' } }];

  const r = record.json;
  const currentStage = String(r.Stage || r.stage || '').toLowerCase().trim();
  const rowNum = r.row_number || (allRows.indexOf(record) + 2);
  const brandName = r.Brand || 'your brand';
  const industry = r.Industry || 'D2C';
  const subject = r.Subject || (`You were curious. So we got to work. Here's ${brandName}'s entire AI ops layer.`);
  const chartUrl = r['Diagram URL'] || r.diagram_url || '';
  const draftJson = r['Draft JSON'] || r.draft_json || '';
  const isAlreadySent = ['sent', 'sending'].includes(currentStage);

  if (action === 'edit') {
    return [{
      json: {
        ...base,
        _found: true,
        is_already_sent: isAlreadySent,
        row_number: rowNum,
        brand: brandName,
        industry,
        subject,
        chart_url: chartUrl,
        draft_json: draftJson,
        first_name: extractFirstName(r.Body),
        current_stage: currentStage
      }
    }];
  }

  // approve / reject: build send-ready HTML body with styled buttons and tracking
  const WEBHOOK_BASE = 'https://n8n-production-0ef21.up.railway.app';
  // Read dynamic destinations and button labels from Draft JSON
  let djData = {};
  try {
    djData = typeof draftJson === 'string' ? JSON.parse(draftJson) : (draftJson || {});
  } catch (e) {}

  let CALL_URL = djData.call_url || 'https://calendly.com/team-grapelabs/30min';
  let WA_URL = djData.whatsapp_url || 'https://wa.me/918388892300?text=Hi%20Kashika,%20saw%20your%20email%20about%20our%20AI%20ops%20layer';
  if (WA_URL.includes('{{brand}}')) {
    WA_URL = WA_URL.replace(/\{\{\s*brand\s*\}\}/gi, encodeURIComponent(brandName));
  }
  const CALL_BTN_TEXT = djData.call_button_text || 'Book a Free Call';
  const WA_BTN_TEXT = djData.whatsapp_text || 'Text me on WhatsApp';

  const qs = (o) => Object.entries(o).map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');
  const common = { email: targetEmail, brand: brandName, industry, subject, followup: 'aiops' };
  const clickUrl = WEBHOOK_BASE + '/webhook/track-click?' + qs({ ...common, button: 'bookcall', dest: CALL_URL });
  const waClickUrl = WEBHOOK_BASE + '/webhook/track-click?' + qs({ ...common, button: 'whatsapp', dest: WA_URL });
  const pixelUrl = WEBHOOK_BASE + '/webhook/track-open?' + qs(common);

  // Styled button table matching template
  const buttonTable = `
<table border="0" cellpadding="0" cellspacing="0" style="margin: 18px 0 16px 0;">
  <tr>
    <td style="padding-right: 12px; padding-bottom: 8px;">
      <a href="${clickUrl}" style="display: inline-block; background-color: #581c87; color: #ffffff; text-decoration: none; padding: 12px 22px; border-radius: 6px; font-weight: 700; font-size: 14px; line-height: 1.2; text-align: center;">${CALL_BTN_TEXT}</a>
    </td>
    <td style="padding-bottom: 8px;">
      <a href="${waClickUrl}" style="display: inline-block; background-color: #25D366; color: #ffffff; text-decoration: none; padding: 12px 22px; border-radius: 6px; font-weight: 700; font-size: 14px; line-height: 1.2; text-align: center;">${WA_BTN_TEXT}</a>
    </td>
  </tr>
</table>`.trim();

  const pixelTag = `<img src="${pixelUrl}" width="1" height="1" style="display:none !important; width:1px; height:1px; border:0; outline:none;" alt="" />`;

  let rawBody = String(r.Body || '').trim();
  rawBody = rawBody
    .replace(/<table[^>]*>[\s\S]*?<\/table>/gi, '')
    .replace(/<img[^>]*>/gi, '')
    .replace(/^=\s*/, '')
    .replace(/\s*[\u2014\u2013]\s*/g, ', ')
    .trim();

  // Strip old raw links to prevent duplicates
  rawBody = rawBody
    .replace(/<a\b[^>]*>.*?<\/a>/gi, '')
    .replace(/https?:\/\/calendly\.com[^\s"<]*/gi, '')
    .replace(/https?:\/\/wa\.me[^\s"<]*/gi, '')
    .trim();

  if (!rawBody.includes('<br>') && !rawBody.includes('<p>')) {
    rawBody = rawBody
      .replace(/\\n\\n/g, '<br><br>')
      .replace(/\n\n/g, '<br><br>')
      .replace(/\\n/g, '<br>')
      .replace(/\n/g, '<br>');
  }

  const diagramHtml = chartUrl ? `
<table border="0" cellpadding="0" cellspacing="0" style="margin: 18px 0 22px 0;">
  <tr>
    <td>
      <a href="${chartUrl}" target="_blank">
        <img src="${chartUrl}" alt="${brandName} AI Ops Layer" width="600" border="0" style="display: block; width: 100%; max-width: 650px; height: auto; border: 1px solid #e5e7eb; border-radius: 6px;" />
      </a>
    </td>
  </tr>
</table>` : '';

  // 1. Check if signature was saved in Draft JSON
  let dynamicSignature = '';
  try {
    const dj = typeof draftJson === 'string' ? JSON.parse(draftJson) : (draftJson || {});
    if (dj.signature_html) dynamicSignature = dj.signature_html;
  } catch (e) {}

  // 2. Fallback signature with Kashika Gupta
  const signatureHtml = dynamicSignature || `
<div style="margin-top: 22px; line-height: 1.45; font-size: 13px; color: #374151;">
  <div style="margin-bottom: 4px;">Best,</div>
  <div style="margin-bottom: 14px; font-weight: 600; color: #111827;">Kashika Gupta</div>
  <div style="border-left: 2px solid #7c3aed; padding-left: 10px; margin-bottom: 18px;">
    <div style="color: #6d28d9; font-weight: 600; font-size: 13px;">Co-Founder, GrapeLabs AI</div>
    <div style="color: #6b7280; font-size: 12px; margin-top: 2px;">Green Park, New Delhi · 110016</div>
    <div style="color: #6b7280; font-size: 12px; margin-top: 2px;">Phone: +91 83888 92300</div>
  </div>
  <div style="font-size: 12px; color: #6b7280; font-style: italic;">
    P.S. The irony isn't lost on us. We used our own infrastructure to find you, track your open, and send you this.
  </div>
</div>`;

  const finalHtmlBody = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 1.55; color: #111827;">
  ${rawBody}
  ${buttonTable}
  ${diagramHtml}
  ${signatureHtml}
  ${pixelTag}
</div>`.trim();

  return [{
    json: {
      ...base,
      _found: true,
      is_already_sent: isAlreadySent,
      row_number: rowNum,
      brand: brandName,
      industry,
      subject,
      body: finalHtmlBody,
      chart_url: chartUrl,
      current_stage: currentStage
    }
  }];
}

// --- edit_text: plain-text reply ---
if (action === 'edit_text') {
  const rows = allRows.filter(item =>
    String(item.json.Stage || item.json.stage || '').toLowerCase().trim() === 'awaiting_edit'
  );
  if (rows.length === 0) {
    return [{ json: { ...base, reason: "No pending edit found. Tap the Edit button on a preview first, then reply with your changes." } }];
  }
  rows.sort((a, b) => new Date(b.json.Timestamp || 0) - new Date(a.json.Timestamp || 0));
  const record = rows[0];
  const r = record.json;
  const rowNum = r.row_number || (allRows.indexOf(record) + 2);
  const resolvedEmail = String(r.Email || r.email || '').toLowerCase().trim();

  return [{
    json: {
      ...base,
      _found: true,
      is_already_sent: false,
      lead_email: resolvedEmail,
      row_number: rowNum,
      brand: r.Brand || 'your brand',
      industry: r.Industry || 'D2C',
      subject: r.Subject || '',
      chart_url: r['Diagram URL'] || r.diagram_url || '',
      draft_json: r['Draft JSON'] || r.draft_json || '',
      previous_body_text: String(r.Body || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 1200),
      first_name: extractFirstName(r.Body),
      current_stage: 'awaiting_edit'
    }
  }];
}

return [{ json: { ...base, reason: 'Unknown button action' } }];

